var data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
var command = data.command || "UNKNOWN";
var speed = data.parameters ? data.parameters.conveyor_speed : 80;
var state = global.get("machineState") || {
    machine_state: "STOPPED",
    buttons: { start_pressed: false, stop_pressed: true, emergency_active: false },
    conveyor_speed_rpm: 0
};
if (command === "START" && !state.buttons.emergency_active) {
    state.machine_state = "RUNNING";
    state.buttons.start_pressed = true;
    state.buttons.stop_pressed = false;
    state.conveyor_speed_rpm = speed;
} else if (command === "STOP") {
    state.machine_state = "STOPPED";
    state.buttons.start_pressed = false;
    state.buttons.stop_pressed = true;
    state.conveyor_speed_rpm = 0;
} else if (command === "EMERGENCY") {
    state.machine_state = "EMERGENCY";
    state.buttons.start_pressed = false;
    state.buttons.stop_pressed = false;
    state.buttons.emergency_active = true;
    state.conveyor_speed_rpm = 0;
} else if (command === "RESET") {
    state.machine_state = "STOPPED";
    state.buttons.emergency_active = false;
    state.buttons.stop_pressed = true;
    state.conveyor_speed_rpm = 0;
}
global.set("machineState", state);
msg.payload = JSON.stringify({
    event: "COMMAND_PROCESSED",
    command: command,
    current_state: state,
    timestamp: new Date().toISOString()
});
return msg;

var state = global.get("machineState") || {
    machine_state: "STOPPED",
    buttons: {
        start_pressed: false,
        stop_pressed: true,
        reset_pressed: false,
        emergency_active: false
    },
    conveyor_speed_rpm: 0,
    sensors: {
        piece_detected: false,
        qr_code: "QR-2026-N2-001"
    }
};
if (state.machine_state === "RUNNING") {
    var variation = (Math.random() * 4 - 2);
    state.conveyor_speed_rpm = Math.max(70, Math.min(100, Math.round(85 + variation)));
    state.sensors.piece_detected = Math.random() > 0.6;
} else {
    state.conveyor_speed_rpm = 0;
    state.sensors.piece_detected = false;
}
var telemetryPayload = {
    timestamp: new Date().toISOString(),
    machine_id: "SMART-40-PLANTA-N2",
    machine_state: state.machine_state,
    buttons: state.buttons,
    conveyor_speed_rpm: state.conveyor_speed_rpm,
    sensors: state.sensors
};
msg.payload = JSON.stringify(telemetryPayload);
return msg;

var state = global.get("machineState") || {
    machine_state: "STOPPED",
    buttons: { start_pressed: false, stop_pressed: true, emergency_active: false },
    conveyor_speed_rpm: 0
};
msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*"
};
msg.payload = {
    status: "SUCCESS",
    data: state,
    timestamp: new Date().toISOString()
};
return msg;

var body = msg.payload || {};
var command = body.command;
if (!command) {
    msg.statusCode = 400;
    msg.payload = { error: "Campo 'command' é obrigatório (START, STOP, EMERGENCY, RESET)" };
    return msg;
}
var state = global.get("machineState") || {
    machine_state: "STOPPED",
    buttons: { start_pressed: false, stop_pressed: true, emergency_active: false },
    conveyor_speed_rpm: 0
};
if (command === "START") {
    state.machine_state = "RUNNING";
    state.buttons.start_pressed = true;
    state.buttons.stop_pressed = false;
    state.conveyor_speed_rpm = body.parameters ? body.parameters.conveyor_speed || 85 : 85;
} else if (command === "STOP") {
    state.machine_state = "STOPPED";
    state.buttons.start_pressed = true;
    state.buttons.stop_pressed = true;
    state.conveyor_speed_rpm = 0;
} else if (command === "EMERGENCY") {
    state.machine_state = "EMERGENCY";
    state.buttons.emergency_active = true;
    state.conveyor_speed_rpm = 0;
} else if (command === "RESET") {
    state.machine_state = "STOPPED";
    state.buttons.emergency_active = false;
    state.buttons.stop_pressed = true;
    state.conveyor_speed_rpm = 0;
}
global.set("machineState", state);
msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*"
};
msg.payload = {
    message: "Comando executado no CLP com sucesso",
    command: command,
    new_state: state
};
return msg;

var state = global.get("machineState");
msg.payload = JSON.stringify({
    timestamp: new Date().toISOString(),
    event: "STATE_CHANGED_VIA_REST",
    machine_state: state.machine_state,
    buttons: state.buttons,
    conveyor_speed_rpm: state.conveyor_speed_rpm
});
return msg;
